-- Catálogo inicial: 4 programas, 8 módulos e 16 aulas.
-- IDs idênticos aos embarcados permitem retomar o progresso offline.
begin;
insert into public.content_programs
  (id, title, tagline, description, topic, level, weeks, outcomes, curriculum, published)
select id, title, tagline, description, topic, level, weeks, outcomes, curriculum, published
from jsonb_to_recordset($catalog$[{"id":"fundamentos_homem_valor","title":"Fundamentos do Homem de Valor","tagline":"Construa sua base: mente, corpo, caráter e propósito.","description":"Um programa completo para estabelecer as fundações da sua evolução pessoal, unindo disciplina mental, física e de propósito.","weeks":2,"topic":"Propósito","level":"intermediario","outcomes":["Clareza de propósito","Autocontrole emocional","Rotina de alto desempenho","Relacionamentos e liderança"],"curriculum":[{"id":"base","title":"Uma base com propósito","lessons":[{"id":"valores","title":"Transforme valores em escolhas","body":"Um valor fica concreto quando orienta uma decisão. Dizer que valoriza a honestidade ganha sentido ao admitir um erro; valorizar a presença aparece ao guardar o celular durante uma conversa.\n\nEscolha um valor importante para você e descreva uma atitude observável que o represente. Evite metas que dependam da aprovação dos outros. Uma ação pequena, repetida, ajuda a aproximar suas escolhas do que você considera importante.","practice":"Escreva um valor e uma ação de hoje que o coloque em prática.","minutes":3,"habit_key":null},{"id":"rotina_minima","title":"Comece por uma rotina possível","body":"Uma rotina precisa caber no seu dia real. Planejar muitas mudanças de uma vez pode dificultar a continuidade. Comece escolhendo um horário e uma atividade que você consegue repetir.\n\nUma leitura curta depois do café, por exemplo, tem um momento de início claro. Em dias difíceis, reduza o tamanho da atividade e retome quando puder. Um registro serve para observar seu caminho, não para medir seu valor pessoal.","practice":"Escolha um horário de leitura e separe o material antes de começar.","minutes":3,"habit_key":"read"}]},{"id":"consistencia","title":"Consistência e responsabilidade","lessons":[{"id":"ambiente","title":"Prepare o ambiente","body":"O ambiente pode facilitar ou atrapalhar uma escolha. Um livro acessível lembra a leitura; notificações frequentes interrompem uma atividade. Observe o que acontece antes de um hábito que deseja manter.\n\nEm vez de depender apenas da vontade, retire um obstáculo: deixe o material pronto, reserve um espaço ou silencie interrupções durante um período combinado. Teste uma mudança por vez para descobrir o que ajuda você.","practice":"Prepare um espaço de estudo e faça uma leitura curta nele.","minutes":3,"habit_key":"read"},{"id":"revisao","title":"Revise sem se punir","body":"Uma revisão útil descreve fatos. “Li em dois dias” informa mais do que “não tenho disciplina”. Olhe para o que aconteceu, quais condições ajudaram e quais dificultaram.\n\nDepois escolha um ajuste possível para a próxima semana. Você pode mudar o horário, reduzir uma meta ou pedir apoio. O objetivo é aprender com a experiência e continuar com um plano que respeite seus limites e suas responsabilidades.","practice":"Anote uma coisa que funcionou e um ajuste para a próxima semana.","minutes":3,"habit_key":null}]}],"published":true},{"id":"lideranca_silenciosa","title":"Liderança Silenciosa","tagline":"Influencie pelo exemplo, não pela imposição.","description":"Desenvolva presença e autoridade natural em qualquer ambiente, sem depender de validação externa.","weeks":2,"topic":"Liderança","level":"avancado","outcomes":["Comunicação assertiva","Presença de liderança","Tomada de decisão sob pressão"],"curriculum":[{"id":"escuta","title":"Presença e escuta","lessons":[{"id":"ouvir","title":"Escute antes de responder","body":"Escutar envolve compreender o que a outra pessoa está tentando comunicar. Durante uma conversa, perceba se você está acompanhando a fala ou apenas preparando uma resposta.\n\nEspere a pessoa concluir e confirme sua compreensão: “Entendi que sua dificuldade é esta; faz sentido?”. A confirmação evita respostas baseadas em suposições. Escutar não exige concordar com tudo, mas cria condições para uma conversa mais clara e respeitosa.","practice":"Em uma conversa, confirme o que entendeu antes de dar sua opinião.","minutes":3,"habit_key":null},{"id":"comunicar","title":"Faça pedidos claros","body":"Um pedido claro descreve uma ação, um contexto e um prazo possível. “Preciso da sua ajuda” pode abrir a conversa, mas deixa detalhes importantes em aberto.\n\nExplique o que precisa, por que isso importa e pergunte se a pessoa consegue assumir o combinado. Dê espaço para negociar. Quando há limites ou desacordo, nomeie o problema sem atacar a pessoa. Clareza e respeito ajudam a evitar expectativas que ninguém combinou.","practice":"Reescreva um pedido usando ação, contexto e prazo negociável.","minutes":3,"habit_key":null}]},{"id":"exemplo","title":"Liderança em prática","lessons":[{"id":"compromissos","title":"Cuide dos compromissos","body":"Confiança se constrói também nos pequenos combinados. Antes de assumir uma tarefa, confira se tem tempo e condições para realizá-la. Dizer sim a tudo pode gerar promessas difíceis de cumprir.\n\nSe perceber que vai atrasar, avise com antecedência, explique a situação e proponha um novo acordo. Assumir responsabilidade inclui reconhecer limites. O exemplo está na forma como você trata os compromissos e as pessoas envolvidas.","practice":"Revise um compromisso pendente e confirme ou renegocie o prazo.","minutes":3,"habit_key":null},{"id":"feedback","title":"Converse sobre melhorias","body":"Uma conversa de melhoria funciona melhor com exemplos concretos. Descreva o que observou e seu impacto, evitando rótulos como “você sempre faz isso”. Depois ouça a perspectiva da outra pessoa.\n\nCombinem um próximo passo pequeno e uma ocasião para revisar. Ao receber uma observação, peça exemplos se precisar e reserve tempo para pensar. Respeito não elimina o desacordo; ajuda a lidar com ele sem humilhação ou imposição.","practice":"Prepare uma observação concreta e uma pergunta aberta para uma conversa.","minutes":3,"habit_key":null}]}],"published":true},{"id":"estoicismo_pratico","title":"Estoicismo Prático","tagline":"Filosofia antiga para problemas modernos.","description":"Aplique princípios estoicos no dia a dia para lidar com adversidade, foco e serenidade.","weeks":2,"topic":"Emoções","level":"iniciante","outcomes":["Gestão de emoções","Foco no que você controla","Resiliência diária"],"curriculum":[{"id":"controle","title":"Foco no que você controla","lessons":[{"id":"escolhas","title":"Separe fatos e escolhas","body":"Você não decide o trânsito, o clima ou a reação de outra pessoa. Pode escolher como se preparar, o que comunicar e qual atitude tomar diante dessas condições. Essa distinção ajuda a direcionar seu esforço.\n\nPense em uma situação recente. Separe o fato, a interpretação que fez e a ação que está ao seu alcance. Aceitar que algo aconteceu não significa aprová-lo: você ainda pode procurar ajuda, estabelecer limites e agir para mudar o que for possível.","practice":"Divida uma preocupação em duas listas: o que posso fazer e o que não depende de mim.","minutes":3,"habit_key":null},{"id":"pausa","title":"Crie uma pausa antes da resposta","body":"Entre perceber um acontecimento e responder, às vezes é possível criar uma pausa. Ao notar pressa para reagir, observe a situação e dê nome ao que está sentindo.\n\nPergunte: “O que sei de fato? Qual resposta combina com meus valores?”. Se for seguro e possível, adie uma mensagem ou uma decisão até conseguir pensar com mais clareza. Uma pausa não resolve todos os problemas; ela abre espaço para uma escolha mais deliberada.","practice":"Reserve alguns minutos em silêncio para refletir sobre uma resposta que quer dar.","minutes":3,"habit_key":"meditate"}]},{"id":"cotidiano","title":"Aplicação no cotidiano","lessons":[{"id":"imprevistos","title":"Prepare uma alternativa","body":"Planos encontram imprevistos. Uma alternativa simples evita tratar qualquer mudança como o fim do plano. Se você costuma ler à noite, pode separar um horário menor em outro momento quando surgir um compromisso.\n\nDefina uma condição e uma resposta: “Se meu horário mudar, vou escolher outro momento possível”. A alternativa precisa ser flexível e respeitar suas necessidades. Adaptar a ação pode ser mais útil do que insistir em um plano que deixou de caber no dia.","practice":"Escreva uma alternativa para um hábito que costuma ser interrompido.","minutes":3,"habit_key":"read"},{"id":"reflexao","title":"Encerre o dia com uma revisão","body":"Uma reflexão breve pode ajudar a perceber padrões. Relembre uma escolha de hoje e observe o que a influenciou. Procure uma atitude que gostaria de repetir e outra que gostaria de ajustar.\n\nEvite transformar a revisão em julgamento sobre quem você é. Registre algo específico e encerre com um próximo passo possível. A proposta é aprender com o dia, mantendo abertura para mudar de ideia e reconhecer situações em que você precisa de apoio.","practice":"Escreva: o que aprendi hoje e qual escolha quero experimentar amanhã.","minutes":3,"habit_key":"meditate"}]}],"published":true},{"id":"corpo_combate","title":"Corpo de Combate","tagline":"Força física como base da disciplina mental.","description":"Organize uma rotina de movimento e descanso com foco em consistência e respeito aos seus limites.","weeks":2,"topic":"Corpo","level":"intermediario","outcomes":["Planejamento da rotina","Consistência nas atividades","Equilíbrio e descanso"],"curriculum":[{"id":"preparacao","title":"Prepare sua consistência","lessons":[{"id":"objetivo","title":"Defina um objetivo possível","body":"Antes de escolher uma rotina de movimento, pense no que deseja e nas condições de que dispõe. Tempo, acesso a espaços e preferências influenciam a continuidade. Um objetivo precisa respeitar suas condições individuais.\n\nEste programa trabalha organização e reflexão, sem prescrever exercícios ou substituir orientação profissional. Você pode começar planejando quando e onde pretende se movimentar e buscar uma orientação adequada para escolher atividades compatíveis com você.","practice":"Anote seu objetivo e dois horários possíveis para uma atividade adequada a você.","minutes":3,"habit_key":null},{"id":"preparar","title":"Reduza os obstáculos para começar","body":"Preparar o necessário com antecedência torna o início mais simples. Separe roupas, confira o local e considere o tempo de deslocamento. Veja se o horário escolhido compete com algum compromisso importante.\n\nSe surgir um impedimento, ajuste o plano sem tentar compensar com esforço excessivo. A proposta é construir uma organização sustentável. Ao escolher e realizar uma atividade, respeite seus limites e a orientação dos profissionais que acompanham você.","practice":"Prepare o material para sua próxima atividade já planejada.","minutes":3,"habit_key":"train"}]},{"id":"continuidade","title":"Mantenha um plano sustentável","lessons":[{"id":"registro","title":"Observe sua experiência","body":"Um registro simples ajuda a entender como a rotina se encaixa na sua vida. Anote a atividade realizada, o tempo reservado e como foi organizar o dia para participar.\n\nEvite usar comparações com outras pessoas como medida de sucesso. Observe suas próprias condições e leve dúvidas sobre exercícios, desconfortos ou mudanças de intensidade a um profissional qualificado. Aqui o foco é acompanhar sua organização, sem definir cargas, técnicas ou metas físicas individuais.","practice":"Depois de uma atividade, registre o que facilitou sua participação e o que precisa ajustar.","minutes":3,"habit_key":null},{"id":"equilibrio","title":"Inclua descanso no planejamento","body":"Uma agenda sustentável reserva espaço para diferentes necessidades: trabalho, relações, movimento e descanso. Preencher todo horário livre com novas metas pode tornar o plano difícil de manter.\n\nRevise sua semana e observe se há compromissos em excesso. Prepare uma transição tranquila para encerrar o dia, conforme suas possibilidades. Necessidades individuais variam; esta reflexão é uma proposta de organização, e não uma orientação clínica sobre sono ou recuperação.","practice":"Escolha um horário viável para começar a encerrar as atividades do dia.","minutes":3,"habit_key":"sleep_early"}]}],"published":true}]$catalog$::jsonb) as p(
  id text, title text, tagline text, description text, topic text, level text,
  weeks integer, outcomes jsonb, curriculum jsonb, published boolean
)
on conflict (id) do nothing;
commit;
